int main(int argc, char **argv) {
    const char *path = argc > 1 ? argv[1] : "/etc/hostname";
    // 파일을 읽기 전용으로 열고 식별 번호를 받는다.
    int fd = open(path, O_RDONLY);
    if (fd < 0) { perror("open"); return 1; }
    char buffer[256];
    ssize_t n;
    // 읽은 길이가 양수인 동안 반복한다.
    while ((n = read(fd, buffer, sizeof(buffer))) > 0) {
        // 이번에 읽은 내용 중 이미 출력한 바이트 수.
        ssize_t sent = 0;
        while (sent < n) {
            // buffer + sent는 아직 출력하지 않은 부분의 시작 주소.
            ssize_t count = write(STDOUT_FILENO, buffer + sent, (size_t)(n - sent));
            if (count <= 0) { perror("write"); close(fd); return 1; }
            sent += count;
        }
    }
    // read 오류를 확인하고 열린 파일을 닫는다.
    if (n < 0) { perror("read"); close(fd); return 1; }
    return close(fd) < 0 ? 1 : 0;
}

