 * 조건을 검사하고 대기 등록·태스크 상태 변경 후 잠듭니다. 생산자가 조건을 변경하고 wake_up을 수행합니다. 깨움은 조건 충족 자체의 보장이 아니므로 재검사가 필요합니다.
 * wait_event 계열로 조건과 대기를 결합합니다. 대기 등록과 조건 변경의 순서를 잘못 맞추면 통지를 놓치는 lost wakeup이 생길 수 있습니다.
 */
int __wake_up(struct wait_queue_head *wq_head, unsigned int mode,
	      int nr_exclusive, void *key)
{
	return __wake_up_common_lock(wq_head, mode, nr_exclusive, 0, key);
}
EXPORT_SYMBOL(__wake_up);

void __wake_up_on_current_cpu(struct wait_queue_head *wq_head, unsigned int mode, void *key)
{
	__wake_up_common_lock(wq_head, mode, 1, WF_CURRENT_CPU, key);
}

/*
 * Same as __wake_up but called with the spinlock in wait_queue_head_t held.
 */
void __wake_up_locked(struct wait_queue_head *wq_head, unsigned int mode, int nr)
{
	__wake_up_common(wq_head, mode, nr, 0, NULL);
}
EXPORT_SYMBOL_GPL(__wake_up_locked);

void __wake_up_locked_key(struct wait_queue_head *wq_head, unsigned int mode, void *key)
{
	__wake_up_common(wq_head, mode, 1, 0, key);
}
EXPORT_SYMBOL_GPL(__wake_up_locked_key);

/* 학습 해설
 * Futex · 사용자 공간 빠른 경로
 * 매 잠금 연산마다 커널에 들어가지 않고 경합이 있을 때만 대기 지원을 받아야 합니다.
 * 평소 잠금 상태는 사용자 메모리의 원자 연산으로 처리합니다. FUTEX_WAIT는 지정 값과 현재 값을 검사해 대기하며 FUTEX_WAKE는 대기자를 깨웁니다. 값 검사와 대기 등록의 경쟁을 처리하는 것이 핵심입니다.
 * 일반 프로그램에서는 pthread mutex·condition 같은 라이브러리를 사용합니다. futex를 직접 쓰면 메모리 순서와 대기 프로토콜까지 구현해야 합니다.
 */
int futex_wait(u32 __user *uaddr, unsigned int flags, u32 val, ktime_t *abs_time, u32 bitset)
{
	struct hrtimer_sleeper timeout, *to;
	struct restart_block *restart;
	int ret;

	to = futex_setup_timer(abs_time, &timeout, flags,
			       current->timer_slack_ns);

	ret = __futex_wait(uaddr, flags, val, to, bitset);

	/* No timeout, nothing to clean up. */
	if (!to)
		return ret;

	hrtimer_cancel(&to->timer);
	destroy_hrtimer_on_stack(&to->timer);

	if (ret == -ERESTARTSYS) {
		restart = &current->restart_block;
		restart->futex.uaddr = uaddr;
		restart->futex.val = val;
		restart->futex.time = *abs_time;
		restart->futex.bitset = bitset;
		restart->futex.flags = flags | FLAGS_HAS_TIMEOUT;

/* 학습 해설
 * RCU · 읽기 보호와 지연 해제
 * 읽기가 많은 구조에서 독자를 매번 배타적으로 잠그지 않고 객체를 교체해야 합니다.
 * 독자는 RCU 읽기 구간에서 공개된 객체를 사용합니다. writer는 새 객체를 공개하고 기존 객체를 제거한 뒤 기존 독자들이 지나가는 grace period를 기다려 해제합니다. synchronize_rcu는 writer끼리의 잠금이 아닙니다.
 * rcu_read_lock·rcu_dereference와 rcu_assign_pointer·call_rcu의 규약을 함께 따릅니다. RCU 구간을 벗어나 포인터를 보관하려면 별도의 수명 보호가 필요합니다.
 */
void synchronize_rcu(void)
{
	unsigned long flags;
	struct rcu_node *rnp;

	RCU_LOCKDEP_WARN(lock_is_held(&rcu_bh_lock_map) ||
			 lock_is_held(&rcu_lock_map) ||
			 lock_is_held(&rcu_sched_lock_map),
			 "Illegal synchronize_rcu() in RCU read-side critical section");
	if (!rcu_blocking_is_gp()) {
		if (rcu_gp_is_expedited())
			synchronize_rcu_expedited();
		else
			synchronize_rcu_normal();
		return;
	}

	// Context allows vacuous grace periods.
	// Note well that this code runs with !PREEMPT && !SMP.
	// In addition, all code that advances grace periods runs at
	// process level.  Therefore, this normal GP overlaps with other
	// normal GPs only by being fully nested within them, which allows
	// reuse of ->gp_seq_polled_snap.
	rcu_poll_gp_seq_start_unlocked(&rcu_state.gp_seq_polled_snap);
	rcu_poll_gp_seq_end_unlocked(&rcu_state.gp_seq_polled_snap);

/* 학습 해설
 * SRCU · 잠들 수 있는 읽기 구간
 * 읽기 보호 구간에서 블로킹이 필요한 경우 일반 RCU 규약만으로 설계하기 어려울 수 있습니다.
 * SRCU는 특정 srcu_struct 도메인의 읽기 구간을 추적합니다. 독자가 잠들 수 있으며 synchronize_srcu는 그 도메인의 기존 읽기 구간 종료를 기다립니다. lock에서 받은 인덱스를 unlock에 전달합니다.
 * srcu_read_lock·srcu_read_unlock을 같은 도메인과 인덱스로 짝지어 사용합니다. 동기화 대기와 자기 읽기 구간이 겹쳐 스스로 기다리는 구조를 피해야 합니다.
 */
void synchronize_srcu(struct srcu_struct *ssp)
{
	if (srcu_might_be_idle(ssp) || rcu_gp_is_expedited())
		synchronize_srcu_expedited(ssp);
	else
		__synchronize_srcu(ssp, true);
}
EXPORT_SYMBOL_GPL(synchronize_srcu);

/**
 * get_state_synchronize_srcu - Provide an end-of-grace-period cookie
 * @ssp: srcu_struct to provide cookie for.
 *
 * This function returns a cookie that can be passed to
 * poll_state_synchronize_srcu(), which will return true if a full grace
 * period has elapsed in the meantime.  It is the caller's responsibility
 * to make sure that grace period happens, for example, by invoking
 * call_srcu() after return from get_state_synchronize_srcu().
 */
unsigned long get_state_synchronize_srcu(struct srcu_struct *ssp)
{
	// Any prior manipulation of SRCU-protected data must happen
	// before the load from ->srcu_gp_seq.
	smp_mb();
	return rcu_seq_snap(&ssp->srcu_sup->srcu_gp_seq);
}
